SELECT 
FROM EDU_TEACHER_MANAGER T
WHERE T.CPNY_ID = #{cpnyId, jdbcType=VARCHAR}
  AND T.ACTIVITY = '1'

    AND (UPPER(T.EMPID) LIKE '%' || UPPER(#{keyword, jdbcType=VARCHAR}) || '%'
         OR CONVERTTOUNSIGN(UPPER(T.TEACHER_NAME)) LIKE '%' || CONVERTTOUNSIGN(UPPER(#{keyword, jdbcType=VARCHAR})) || '%')


    AND T.TEACH_FIELD_CODE = #{teachFieldCode, jdbcType=VARCHAR}


    AND T.TEACH_LEVEL_CODE = #{teachLevelCode, jdbcType=VARCHAR}


    AND T.TEACH_STATUS_CODE = #{teachStatusCode, jdbcType=VARCHAR}

ORDER BY T.CREATE_DATE DESC

SELECT 
FROM EDU_TEACHER_MANAGER T
WHERE T.TEACHER_NO = #{teacherNo, jdbcType=VARCHAR}
  AND T.CPNY_ID = #{cpnyId, jdbcType=VARCHAR}

mapper.update:
UPDATE EDU_TEACHER_MANAGER
   SET ACTIVITY = '0'
 WHERE TEACHER_NO = #{teacherNo, jdbcType=VARCHAR}
   AND CPNY_ID = #{cpnyId, jdbcType=VARCHAR}
